def transform(grid):
    """Extend each 3-marked plus's center color along its row and column.

    Existing 3 markers are preserved. Horizontal rays are drawn first, then
    vertical rays, so vertical rays take precedence where rays intersect.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c] not in (0, 3) and grid[r-1][c] == 3 and grid[r+1][c] == 3 and
                grid[r][c-1] == 3 and grid[r][c+1] == 3):
                centers.append((r, c, grid[r][c]))

    # Rays extend only up to the boundary/other plus structures: the arms
    # form blockers, with original colored centers retained.
    for r, c, color in centers:
        if color == 0:
            continue
        for j in range(w):
            if grid[r][j] == 0:
                out[r][j] = color
    for r, c, color in centers:
        if color == 0:
            continue
        for i in range(h):
            if grid[i][c] == 0:
                out[i][c] = color
    return out

